const raw = $json.output;
let result;

try {
  result = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch {
  result = {
    estado: 'ERROR',
    mensaje: 'La salida del AI Agent no fue JSON válido.',
    ordenCreada: false,
    resumenPublicado: false
  };
}

return [{
  json: {
    estado: result?.estado === 'ERROR' ? 'ERROR' : 'EXITO',
    mensaje: String(result?.mensaje ?? 'Operación finalizada.'),
    ordenCreada: result?.ordenCreada === true,
    resumenPublicado: result?.resumenPublicado === true
  }
}];

const detail = $json.error?.message ?? $json.message ?? 'Falló la conexión, autenticación o una herramienta MCP.';

return [{
  json: {
    estado: 'ERROR',
    mensaje: String(detail),
    ordenCreada: false,
    resumenPublicado: false
  }
}];
